```python
from collections import deque

def find_path(graph, start, goal):
    if start == goal:
        return [start]  # Path found with a single node

    if start not in graph:
        return None  # Invalid start node

    queue = deque([(start, [start])])  # Initialize queue with start node and path list
    visited = set()  # To keep track of visited nodes to avoid cycles

    while queue:
        current_node, path = queue.popleft()
        visited.add(current_node)

        for neighbor in graph[current_node]:
            if neighbor not in visited:
                if neighbor == goal:
                    return path + [neighbor]  # Goal reached
                else:
                    queue.append((neighbor, path + [neighbor]))  # Add neighbor to queue and extend path

    return None  # Goal is unreachable

