def find_path(graph, start, goal):
    def dfs(node, visited, path):
        if node == goal:
            return path + [goal]

        visited.add(node)
        path.append(node)

        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                new_path = dfs(neighbor, visited, path)
                if new_path:
                    return new_path

        path.pop()
        visited.remove(node)
        return None

    visited = set()
    return dfs(start, visited, [start])

