def find_path(graph, start, goal):
    def explore(node, path):
        if node == goal:
            return path
        for neighbor in graph[node]:
            if neighbor not in path:
                new_path = explore(neighbor, path + [neighbor])
                if new_path:
                    return new_path
        return None

    return explore(start, [start])

